class Solution:
    def circuit(self, events: list[list], threshold: int, cooldown: float) -> list[bool]:
        failures=0
        open_until=None
        allowed=[]
        for now,success in events:
            if open_until is not None and now<open_until:
                allowed.append(False)
                continue
            probe=open_until is not None
            allowed.append(True)
            if success:
                failures=0
                open_until=None
            elif probe:
                open_until=now+cooldown
            else:
                failures+=1
                if failures>=threshold:open_until=now+cooldown
        return allowed

